<main class="public-form-page"><section class="panel"><div class="public-form-context"><span class="kpi-symbol lavender"><?= icon('spark') ?></span><h1>Tout commence par un projet.</h1><p>Bienvenue, <?= e($user['name']) ?>. Donnez un premier cap à votre équipe.</p></div><?php if($user['role']==='admin'): ?><form method="post" action="/projects" class="stack"><?= csrf() ?><input type="hidden" name="_return" value="/"><label>Nom du projet<input name="name" required maxlength="120" placeholder="Expérience digitale"></label><label>Clé des tickets<input name="key" pattern="[A-Za-z][A-Za-z0-9]{1,9}" required placeholder="DIG"><small>2 à 10 lettres ou chiffres, en commençant par une lettre.</small></label><label>Description<textarea name="description" rows="3"></textarea></label><?php $pickerName=''; $pickerMark=['icon'=>'folder','color'=>'#7166eb']; $pickerLabel='Identité du projet'; require ROOT.'/app/Views/partials/appearance-picker.php'; ?><button class="button primary">Créer le premier projet <?= icon('arrow') ?></button></form><?php else: ?><p class="help-text">Un administrateur doit créer le premier projet avant que vous puissiez commencer.</p><?php endif; ?></section></main>
